/*
 * Games API: talks to resources/apis.php (the `game` table).
 *
 *   GET    apis.php/game                    -> all games
 *   POST   apis.php/game                    -> add a game   (game_id is generated by PHP)
 *   PUT    apis.php/game/game_id/G0001      -> update a game
 *   DELETE apis.php/game/game_id/G0001      -> delete a game
 *
 * The database uses snake_case columns and returns every value as a string
 * (price "29.99", rating "3.5", platform "PC, Xbox"). fromRow() converts a row
 * into the shape the Vue pages use, and toRow() converts it back.
 */

const API = (import.meta.env.VITE_API_URL ?? `${import.meta.env.BASE_URL}resources/apis.php`).replace(/\/$/, '')

export function toSlug(title) {
    return String(title)
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '')
}

/* ---------------- low level request ---------------- */
async function request(method, path, body) {
    let res
    try {
        res = await fetch(`${API}${path}`, {
            method,
            headers: body ? { 'Content-Type': 'application/json' } : undefined,
            body: body ? JSON.stringify(body) : undefined,
        })
    } catch (e) {
        throw new Error('Cannot reach the server.')
    }

    // read as text first: an empty or HTML reply would make res.json() throw a confusing error
    const text = await res.text()
    let data = null
    if (text) {
        try {
            data = JSON.parse(text)
        } catch (e) {
            throw new Error('The server sent an unexpected reply (is PHP running?).')
        }
    }
    if (!res.ok) throw new Error(data?.error || `Request failed (${res.status})`)
    return data
}

/* ---------------- row <-> game ---------------- */
const num = (v) => {
    const n = Number(v)
    return Number.isFinite(n) ? n : 0
}

function fromRow(r) {
    // MySQL can hold 0000-00-00 for "no date"
    const date = r.release_date && !String(r.release_date).startsWith('0000') ? r.release_date : ''
    return {
        id: r.game_id,
        title: r.title,
        genre: r.genre,
        platforms: String(r.platform || '')
            .split(',')
            .map((p) => p.trim())
            .filter(Boolean),
        ownerId: r.developer, // developer_id of the creator who published it
        releaseDate: date,
        year: date ? new Date(date).getFullYear() : null,
        description: r.description || '',
        img: r.image || '', // a data: URI when the image is stored, '' when empty
        url: r.url || '',
        price: num(r.price),
        rating: num(r.rating),
    }
}

const columns = {
    title: 'title',
    genre: 'genre',
    ownerId: 'developer',
    releaseDate: 'release_date',
    description: 'description',
    img: 'image',
    url: 'url',
    price: 'price',
    rating: 'rating',
}

function toRow(game) {
    const row = {}
    for (const key in columns) {
        if (game[key] !== undefined) row[columns[key]] = game[key]
    }
    if (game.platforms) row.platform = game.platforms.join(', ')
    return row
}

/* ---------------- reads (cached until a write happens) ---------------- */
let cache = null

export function getGames({ force = false } = {}) {
    if (!cache || force) {
        cache = request('GET', '/game').then((rows) => {
            if (!Array.isArray(rows)) throw new Error('The server sent an unexpected reply.')
            return rows.map(fromRow)
        })
        // do not keep a failed request, so "Try again" really retries
        cache.catch(() => { cache = null })
    }
    return cache.then((list) => list.map((g) => ({ ...g })))
}

export async function getGame(slug) {
    const games = await getGames()
    return games.find((g) => toSlug(g.title) === slug) || null
}

/* ---------------- writes ---------------- */
// NOT NULL columns without a default must always be sent, so give them safe values.
export async function createGame(game) {
    const row = { url: '', rating: 0, image: '', description: '', ...toRow(game) }
    const res = await request('POST', '/game', row)
    cache = null
    return { ...game, id: res.game_id }
}

export async function updateGame(id, patch) {
    const row = toRow(patch)
    if (!Object.keys(row).length) return
    await request('PUT', `/game/game_id/${encodeURIComponent(id)}`, row)
    cache = null
}

export async function deleteGame(id) {
    await request('DELETE', `/game/game_id/${encodeURIComponent(id)}`)
    cache = null
}